// Package catalog is the effect catalog: the 245 demo effects, their parameter schemas,
// and the codec that turns an EFFECT packet body into editable values and back.
//
// Everything here is driven by effects.json (in the data dir, generated by tools/cnf2json.py),
// which is computed from Konami's demoeffect.cnf plus the 245 generated launchers and
// validated against shipped packets.
// Nothing about an effect is inferred at runtime: exec_type, the data base offset and the
// d-index offsets are all fixed properties of the id.
package catalog

import (
	"encoding/json"
	"fmt"
	"os"
	"sort"
)

// EffectTag is the CHARA class bit every demo effect id carries: effect_id = EffectTag | composer_id.
const EffectTag int32 = 0x01000000

const composerMask int32 = 0xFFFFF

// C types that can appear in an effect's Data struct.
const (
	TInt     = "int"
	TFloat   = "float"
	TSVector = "SVECTOR" // 4 x s16, align 2
	TIVector = "IVECTOR" // 4 x s32, align 16
	TFVector = "FVECTOR" // 4 x f32, align 16
	TChar    = "char"    // only ever char[128] (MaxInputString)
)

// Param is one d-indexed field of an effect's Data struct.
//
// Name keeps the composer's d-index, which is an index into the effect's full call list and
// therefore HAS HOLES (0107_NewWaveSplash even starts at d1). Never renumber 0..N-1.
type Param struct {
	Name       string
	Member     string // C member the field feeds, when the .cnf named one
	CType      string
	Widget     string // MaxInputFloat, MaxInputSelectColor, MaxInputPoint, ...
	UI         string // the widget's UI kind ("vec3-float", "string-128", ...)
	Implicit   bool   // filled from scene state by the composer, no dialog
	LabelEN    string
	LabelJA    string
	ByteOffset int // within the Data struct, not the packet
	ByteSize   int
	ArrayLen   int // 0 unless char[128]
	Default    *float64
	DefaultVec []float64       // vector widgets ship a per-component default
	DefaultStr string          // combo/list widgets default by label
	DefaultRaw json.RawMessage // MaxInputPoint's {rot,pos}, and anything else exotic
	Min, Max   *float64

	// Engine-derived, merged from effect_limits.json (see limits.go). The .cnf declares
	// no ranges, so without these a user can set a value the engine cannot survive.
	Units        Units
	EngineClamps bool   // false => the raw value reaches the renderer. Dangerous.
	OutOfRange   string // what goes wrong out of range, in plain English
	LimitSource  string // file:line in the Konami tree
}

// Effect is one catalog entry: a composer id, its packet geometry and its parameter schema.
type Effect struct {
	ID             int32 // composer id (the hex prefix of the launcher's source file)
	EffectID       int32 // EffectTag | ID -- what goes in the packet
	CName          string
	Launcher       string
	SourceFile     string
	DisplayEN      string
	DisplayJA      string
	ExecType       int // 0 = fire-and-forget, 1 = lifetime actor. Fixed per id; never invent one.
	DataBaseOffset int // 0 for exec 0, 16 for exec 1 (the [life,0,0,0] preamble)
	DataStructSize int
	PacketBodySize int // packet size - 16
	Params         []Param
	NoBirth        bool
	ForceEffect    bool
	EfctOn         *int // command id that shows the effect, via DM_SendEffectMessage
	EfctOff        *int
	AddSrc         []string // models/textures the effect needs staged
}

// Catalog is the loaded effects.json.
type Catalog struct {
	effects []*Effect
	byID    map[int32]*Effect
}

// ---- effects.json ------------------------------------------------------------

type jsonOptions struct {
	NoBirth     bool     `json:"no_birth"`
	ForceEffect bool     `json:"force_effect"`
	EfctOn      *int     `json:"efct_on"`
	EfctOff     *int     `json:"efct_off"`
	AddSrc      []string `json:"add_src"`
}

type jsonParam struct {
	Name       string          `json:"name"`
	Member     *string         `json:"member"`
	CType      string          `json:"ctype"`
	ArrayLen   *int            `json:"arrayLen"`
	Widget     string          `json:"widget"`
	UI         string          `json:"ui"`
	Implicit   bool            `json:"implicit"`
	LabelJA    string          `json:"label_ja"`
	LabelEN    *string         `json:"label_en"`
	Default    json.RawMessage `json:"default"`
	Min        *float64        `json:"min"`
	Max        *float64        `json:"max"`
	ByteOffset int             `json:"byteOffset"`
	ByteSize   int             `json:"byteSize"`
}

type jsonEffect struct {
	ID             int32       `json:"id"`
	EffectID       int32       `json:"effectId"`
	CName          string      `json:"cname"`
	Launcher       string      `json:"launcher"`
	SourceFile     string      `json:"sourceFile"`
	DisplayJA      string      `json:"displayName_ja"`
	DisplayEN      *string     `json:"displayName_en"`
	Options        jsonOptions `json:"options"`
	ExecType       int         `json:"execType"`
	DataBaseOffset int         `json:"dataBaseOffset"`
	DataStructSize int         `json:"dataStructSize"`
	PacketBodySize int         `json:"packetBodySize"`
	Params         []jsonParam `json:"params"`
}

// Load reads effects.json and checks every entry against the layout rules:
// a bad byteOffset or a body size that disagrees with the bake formula is a catalog bug,
// and shipping one silently would desync the packet walker.
func Load(path string) (*Catalog, error) {
	raw, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	var entries []jsonEffect
	if err := json.Unmarshal(raw, &entries); err != nil {
		return nil, fmt.Errorf("%s: %w", path, err)
	}

	c := &Catalog{byID: make(map[int32]*Effect, len(entries))}
	defer func() { _, _ = c.LoadLimits(limitsPathFor(path)) }()
	for i := range entries {
		e, err := convert(&entries[i])
		if err != nil {
			return nil, fmt.Errorf("%s: effect 0x%x: %w", path, entries[i].ID, err)
		}
		if _, dup := c.byID[e.ID]; dup {
			return nil, fmt.Errorf("%s: duplicate effect id 0x%x", path, e.ID)
		}
		c.byID[e.ID] = e
		c.effects = append(c.effects, e)
	}
	sort.Slice(c.effects, func(i, j int) bool { return c.effects[i].ID < c.effects[j].ID })
	return c, nil
}

func convert(j *jsonEffect) (*Effect, error) {
	e := &Effect{
		ID:             j.ID,
		EffectID:       j.EffectID,
		CName:          j.CName,
		Launcher:       j.Launcher,
		SourceFile:     j.SourceFile,
		DisplayJA:      j.DisplayJA,
		ExecType:       j.ExecType,
		DataBaseOffset: j.DataBaseOffset,
		DataStructSize: j.DataStructSize,
		PacketBodySize: j.PacketBodySize,
		NoBirth:        j.Options.NoBirth,
		ForceEffect:    j.Options.ForceEffect,
		EfctOn:         j.Options.EfctOn,
		EfctOff:        j.Options.EfctOff,
		AddSrc:         j.Options.AddSrc,
	}
	if j.DisplayEN != nil {
		e.DisplayEN = *j.DisplayEN
	}
	if e.EffectID != EffectTag|e.ID {
		return nil, fmt.Errorf("effectId 0x%08x != 0x01000000|0x%x", e.EffectID, e.ID)
	}
	switch e.ExecType {
	case 0:
		if e.DataBaseOffset != 0 {
			return nil, fmt.Errorf("exec 0 with dataBaseOffset %d", e.DataBaseOffset)
		}
	case 1:
		if e.DataBaseOffset != 16 {
			return nil, fmt.Errorf("exec 1 with dataBaseOffset %d", e.DataBaseOffset)
		}
	default:
		return nil, fmt.Errorf("exec_type %d does not exist", e.ExecType)
	}
	if want := e.PacketSize() - 16; e.PacketBodySize != want {
		return nil, fmt.Errorf("packetBodySize %d, bake formula says %d", e.PacketBodySize, want)
	}

	for i := range j.Params {
		p, err := convertParam(&j.Params[i])
		if err != nil {
			return nil, fmt.Errorf("%s: %w", j.Params[i].Name, err)
		}
		if p.ByteOffset+p.ByteSize > e.DataStructSize {
			return nil, fmt.Errorf("%s: ends at %d, past the %d-byte Data struct", p.Name, p.ByteOffset+p.ByteSize, e.DataStructSize)
		}
		e.Params = append(e.Params, p)
	}
	return e, nil
}

func convertParam(j *jsonParam) (Param, error) {
	p := Param{
		Name:       j.Name,
		CType:      j.CType,
		Widget:     j.Widget,
		UI:         j.UI,
		Implicit:   j.Implicit,
		LabelJA:    j.LabelJA,
		ByteOffset: j.ByteOffset,
		ByteSize:   j.ByteSize,
		Min:        j.Min,
		Max:        j.Max,
	}
	if j.Member != nil {
		p.Member = *j.Member
	}
	if j.LabelEN != nil {
		p.LabelEN = *j.LabelEN
	}
	if j.ArrayLen != nil {
		p.ArrayLen = *j.ArrayLen
	}
	size, err := typeSize(p.CType, p.ArrayLen)
	if err != nil {
		return p, err
	}
	if size != p.ByteSize {
		return p, fmt.Errorf("%s is %d bytes, catalog says %d", p.CType, size, p.ByteSize)
	}
	if err := decodeDefault(&p, j.Default); err != nil {
		return p, err
	}
	return p, nil
}

// The .cnf defaults are polymorphic: a number, a per-component list, a combo label, or
// MaxInputPoint's {rot,pos}. Keep the raw form so a panel can use whatever it understands.
func decodeDefault(p *Param, raw json.RawMessage) error {
	if len(raw) == 0 || string(raw) == "null" {
		return nil
	}
	p.DefaultRaw = raw
	var v any
	if err := json.Unmarshal(raw, &v); err != nil {
		return fmt.Errorf("default: %w", err)
	}
	switch v := v.(type) {
	case float64:
		p.Default = &v
	case string:
		p.DefaultStr = v
	case []any:
		for _, el := range v {
			f, ok := el.(float64)
			if !ok {
				return nil // a non-numeric list is not a component default; DefaultRaw keeps it
			}
			p.DefaultVec = append(p.DefaultVec, f)
		}
	}
	return nil
}

func typeSize(ctype string, arrayLen int) (int, error) {
	switch ctype {
	case TInt, TFloat:
		return 4, nil
	case TSVector:
		return 8, nil
	case TIVector, TFVector:
		return 16, nil
	case TChar:
		return arrayLen, nil
	}
	return 0, fmt.Errorf("unknown ctype %q", ctype)
}

// ---- lookup ------------------------------------------------------------------

func (c *Catalog) ByID(composerID int32) *Effect { return c.byID[composerID] }

// ByEffectID takes the packet's effect_id (0x01000000|composer). A foreign class tag is
// not an effect and returns nil rather than being silently masked into one.
func (c *Catalog) ByEffectID(effectID int32) *Effect {
	if effectID&^composerMask != EffectTag {
		return nil
	}
	return c.byID[effectID&composerMask]
}

// All returns the effects in composer-id order.
func (c *Catalog) All() []*Effect {
	out := make([]*Effect, len(c.effects))
	copy(out, c.effects)
	return out
}

// ForBody looks up the effect of a DEMO_EFFECT packet body (effect_id at body[0x00]).
func (c *Catalog) ForBody(body []byte) *Effect {
	if len(body) < 8 {
		return nil
	}
	return c.ByEffectID(i32(body, 0x00))
}

// Param finds a parameter by its d-name ("d0", "d5", ...).
func (e *Effect) Param(name string) *Param {
	for i := range e.Params {
		if e.Params[i].Name == name {
			return &e.Params[i]
		}
	}
	return nil
}
